<?php
/** SchoolOS 5.3 role workspaces and scoped family workflows. */
if(!defined('SCHOOLOS_EXPERIENCE')){http_response_code(404);exit;}
function px_schema():array{return [
"CREATE TABLE IF NOT EXISTS px_post_meta(tenant_id BIGINT UNSIGNED NOT NULL,post_id BIGINT UNSIGNED NOT NULL,audience VARCHAR(20) NOT NULL DEFAULT 'families',location VARCHAR(180) NOT NULL DEFAULT '',PRIMARY KEY(tenant_id,post_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS px_meals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,post_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,meal_on DATE NOT NULL,choice VARCHAR(180) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY(tenant_id,post_id,student_id,meal_on)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS px_threads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS px_members(tenant_id BIGINT UNSIGNED NOT NULL,thread_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,last_read BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,thread_id,user_id),INDEX(tenant_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS px_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,thread_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,client_key CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(tenant_id,user_id,client_key),INDEX(tenant_id,thread_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS px_live(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,teacher_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,session_name VARCHAR(100) NOT NULL,title VARCHAR(180) NOT NULL,provider VARCHAR(20) NOT NULL,join_url VARCHAR(1000) NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'scheduled',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,class_id,starts_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS px_peers(tenant_id BIGINT UNSIGNED NOT NULL,lesson_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,peer_key CHAR(32) NOT NULL UNIQUE,last_seen DATETIME NOT NULL,PRIMARY KEY(tenant_id,lesson_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS px_signals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,lesson_id BIGINT UNSIGNED NOT NULL,from_user BIGINT UNSIGNED NOT NULL,to_user BIGINT UNSIGNED NOT NULL,from_key CHAR(32) NOT NULL,to_key CHAR(32) NOT NULL,kind VARCHAR(12) NOT NULL,payload MEDIUMTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,lesson_id,to_user,id),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function px_ready():bool{foreach(['px_post_meta','px_meals','px_threads','px_members','px_messages','px_live','px_peers','px_signals'] as $table)if(!xp_has($table))return false;return true;}
function px_install():void{global $pdo;foreach(px_schema() as $s)$pdo->exec($s);}
function px_actor():array{$u=me();if(!$u||(int)($u['tenant_id']??0)<1||!in_array($u['role'],['school_admin','teacher','parent','student','staff','admissions'],true))throw new RuntimeException('A school account is required.');$a=q('SELECT * FROM users WHERE tenant_id=? AND id=? AND active=1',[$u['tenant_id'],$u['id']])->fetch();if(!$a||$a['role']!==$u['role'])throw new RuntimeException('Account is no longer authorized.');return $a;}
function px_form(string $action,string $button,array $fields=[]):void{echo '<form method="post" class="px-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="px_action" value="'.e($action).'">';foreach($fields as $key=>$val)echo '<input type="hidden" name="'.e($key).'" value="'.e($val).'">';echo '<button class="btn">'.e($button).'</button></form>';}
function px_notice(string $text):void{echo '<div class="px-flash '.(str_starts_with($text,'Error:')?'is-error':'is-success').'" role="'.(str_starts_with($text,'Error:')?'alert':'status').'"><strong>'.(str_starts_with($text,'Error:')?'Please check this':'Done').'</strong><span>'.e($text).'</span></div>';}
function px_can_section(array $u,string $s):bool{if(in_array($u['role'],['school_admin','platform_super_admin'],true))return true;if($s==='operations')return in_array($u['role'],['staff','teacher'],true)&&xp_has('op_roles')&&(bool)g('SELECT COUNT(*) FROM op_roles WHERE tenant_id=? AND user_id=?',[$u['tenant_id'],$u['id']]);if($s==='intelligence')return in_array($u['role'],['staff','teacher'],true)&&xp_has('ix_roles')&&(bool)g('SELECT COUNT(*) FROM ix_roles WHERE tenant_id=? AND user_id=?',[$u['tenant_id'],$u['id']]);if($s==='services')return in_array($u['role'],['parent','student'],true)||(in_array($u['role'],['teacher','staff'],true)&&xp_has('sv_roles')&&(bool)g('SELECT COUNT(*) FROM sv_roles WHERE tenant_id=? AND user_id=?',[$u['tenant_id'],$u['id']]));return true;}
function px_role_groups(array $u,array $groups):array{$role=$u['role'];$wallet=xp_has('ix_settings')&&ix_setting((int)($u['tenant_id']??0),'wallet_enabled');if($wallet&&in_array($role,['parent','student'],true))$groups['Your prepaid account']=['wallet'];if($role==='parent')return ['Your family'=>array_merge(['workspace','family','chat'],$wallet?['wallet']:[]),'School community'=>['announcements','services'],'Help & account'=>['welcome','support']];if($role==='student')return ['Your learning journey'=>['workspace','learning','chat'],'Your school life'=>array_merge(['announcements','school_day','services'],$wallet?['wallet']:[]),'Help & account'=>['welcome']];if($role==='teacher'){$g=['Your teaching studio'=>['workspace','learning','chat'],'Families & community'=>['family','announcements'],'Help & account'=>['welcome','support']];if(xp_has('hr_employees')&&g('SELECT id FROM hr_employees WHERE tenant_id=? AND user_id=?',[$u['tenant_id'],$u['id']]))$g['Your professional day']=['employment'];foreach(['operations'=>'Assigned operations','services'=>'Library & staff services','intelligence'=>'Assigned insights'] as $s=>$label)if(px_can_section($u,$s))$g[$label]=[$s];return $g;}if($role==='staff'){$g=['Your working day'=>['workspace','tasks','chat','announcements']];if(xp_has('hr_employees')&&g('SELECT id FROM hr_employees WHERE tenant_id=? AND user_id=?',[$u['tenant_id'],$u['id']]))$g['Your employment']=['employment'];foreach(['operations'=>'Your operational role','services'=>'Your service desk','intelligence'=>'Authorized reports'] as $s=>$label)if(px_can_section($u,$s))$g[$label]=[$s];$g['Help & account']=['welcome','support'];return $g;}if($role==='school_admin')$groups['Families & care']=['family'];if(in_array($role,['school_admin','admissions'],true))$groups['Conversations']=['chat'];return $groups;}
function px_role_intro(array $u):array{return match($u['role']){'parent'=>['YOUR FAMILY COMPASS','A closer connection to every child.','Switch children, follow learning, plan the week and talk with your school.'],'teacher'=>['YOUR TEACHING STUDIO','Make room for your next great lesson.','Your classes, learning activities, live lessons and conversations, together.'],'student'=>['YOUR LEARNING JOURNEY','One discovery at a time.','Continue your courses, join a lesson and celebrate your progress.'],'school_admin'=>['YOUR SCHOOL COMMAND CENTRE','A clear view. A purposeful next step.','People, priorities and approvals that need your attention.'],default=>['YOUR WORKSPACE','Your role. Your priorities.','Find the work and conversations assigned to you.']};}
function px_family_hub(array $u,array $children,array $s):void{echo '<section class="px-family-hub"><div class="px-profile"><span class="px-avatar">'.e(mb_substr($s['name'],0,1)).'</span><div><span class="px-kicker">YOUR CHILD’S SCHOOL DAY</span><h3>'.e($s['name']).'</h3><p>'.e($s['class_name']).' · '.e($s['student_no']).'</p></div></div><div class="px-feature-grid">';foreach([['Learning & progress','results','CA, exams and published results','▥'],['School day','attendance','Attendance and homework','◷'],['Fees & receipts','fees','Balances and branded receipts','₦'],['Plan your week','calendar','Events, bookings and daily meals','▦'],['Talk to your school','messages','Multiple recipients and live chat','✉'],['Safe & cared for','pickup','Pickup, transport and absence','♡']] as [$t,$v,$d,$i])echo '<a class="px-feature" href="?s=family&amp;child='.(int)$s['id'].'&amp;view='.$v.'"><span>'.$i.'</span><h3>'.e($t).'</h3><p>'.e($d).'</p><b>Explore →</b></a>';echo '</div></section>';}
function px_results(array $u,array $s):void{$tid=(int)$u['tenant_id'];$sid=(int)$s['id'];$rows=q("SELECT a.session_name,a.term_name,sub.name subject,SUM(CASE WHEN a.category='ca' THEN sc.score/a.max_score*a.weight ELSE 0 END) ca,SUM(CASE WHEN a.category='exam' THEN sc.score/a.max_score*a.weight ELSE 0 END) exam,SUM(sc.score/a.max_score*a.weight) total,SUM(a.weight) weight FROM ac_scores sc JOIN ac_assessments a ON a.id=sc.assessment_id AND a.tenant_id=sc.tenant_id JOIN subjects sub ON sub.id=a.subject_id AND sub.tenant_id=a.tenant_id JOIN ac_term_approvals p ON p.tenant_id=a.tenant_id AND p.class_id=a.class_id AND p.session_name=a.session_name AND p.term_name=a.term_name WHERE sc.tenant_id=? AND sc.student_id=? AND sc.status='approved' AND p.status='published' AND a.max_score>0 GROUP BY a.session_name,a.term_name,sub.id,sub.name ORDER BY a.session_name DESC,a.term_name,sub.name",[$tid,$sid])->fetchAll();echo '<p class="muted">CA and examination contributions use the school’s configured weights. Only approved marks in a published term are shown.</p>';if($rows){$out=[];foreach($rows as $r)$out[]=[$r['session_name'],$r['term_name'],$r['subject'],number_format((float)$r['ca'],2),number_format((float)$r['exam'],2),number_format((float)$r['total'],2).' / '.number_format((float)$r['weight'],2),grade((float)$r['total'])];pp_table($out,['Session','Term','Subject','CA contribution','Exam contribution','Total','Grade']);}else echo '<p>No published CA/exam breakdown yet. Legacy total-only records are listed below; no missing marks are invented.</p>';}
function px_audience(array $p):string{$aud=xp_has('px_post_meta')?g('SELECT audience FROM px_post_meta WHERE tenant_id=? AND post_id=?',[$p['tenant_id'],$p['id']]):'families';$label=['families'=>'School families','students'=>'Students · guardians may view the details','parents'=>'Parents / guardians','all'=>'Whole school community','staff'=>'Staff only'][$aud]??'School families';return $label.(!empty($p['student_id'])?' · invited child':(!empty($p['class_id'])?' · selected class':''));}
function px_event(array $p):void{echo '<details class="px-event"'.((int)($_GET['event']??0)===(int)$p['id']?' open':'').'><summary><span class="px-event-date">'.e($p['starts_at']?date('d M',strtotime($p['starts_at'])):'Date to be confirmed').'</span><span>'.e($p['title']).'<small>'.e(px_audience($p)).'</small></span><b>View details +</b></summary><div><p>'.nl2br(e($p['body'])).'</p><p>Location: '.e(xp_has('px_post_meta')?(g('SELECT location FROM px_post_meta WHERE tenant_id=? AND post_id=?',[$p['tenant_id'],$p['id']])?:'To be confirmed'):'To be confirmed').'</p><dl><dt>Starts</dt><dd>'.e($p['starts_at']?date('D, j M Y · H:i',strtotime($p['starts_at'])).' WAT':'To be confirmed').'</dd><dt>Ends</dt><dd>'.e($p['ends_at']?date('D, j M Y · H:i',strtotime($p['ends_at'])).' WAT':'To be confirmed').'</dd><dt>Who can attend?</dt><dd>'.e(px_audience($p)).'</dd></dl></div></details>';}
function px_meal_days(array $p):array{if(!$p['starts_at']||!$p['ends_at'])return [];$start=new DateTimeImmutable(substr($p['starts_at'],0,10));$end=new DateTimeImmutable(substr($p['ends_at'],0,10));$days=[];for($d=$start;$d<=$end&&count($days)<31;$d=$d->modify('+1 day'))$days[]=$d->format('Y-m-d');return $days;}
function px_meal_save(array $u):string{if($u['role']!=='parent')throw new RuntimeException('Linked parent required.');return xp_tx(function()use($u){$s=pp_child($u,(int)($_POST['child']??0));$p=pp_post($u,$s,(int)($_POST['post_id']??0),true);if($p['kind']!=='meals')throw new RuntimeException('Meal menu unavailable.');$day=pp_date(xp_text('meal_on',10));if(!in_array($day,px_meal_days($p),true)||$day<date('Y-m-d'))throw new RuntimeException('Choose an available future menu date.');$choice=xp_text('choice',180);$options=json_decode($p['options_json']??'[]',true);if(!is_array($options)||!in_array($choice,$options,true))throw new RuntimeException('Choose a school-published meal option.');q('INSERT INTO px_meals(tenant_id,post_id,student_id,user_id,meal_on,choice) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),choice=VALUES(choice)',[$u['tenant_id'],$p['id'],$s['id'],$u['id'],$day,$choice]);audit('family.meal.daily','student',$s['id'].':'.$day);return 'Meal choice saved for '.$s['name'].' on '.date('l, j M',strtotime($day)).'.';});}
function px_meal_view(array $u,array $s,array $p):void{echo '<article class="px-menu"><h3>'.e($p['title']).'</h3><p>'.e($p['body']).'</p>';$days=px_meal_days($p);if(!$days){echo '<p>The school needs to publish the menu’s start and end dates to enable daily choices. Previous responses remain saved.</p></article>';return;}echo '<div class="px-meal-grid">';$opts=json_decode($p['options_json']??'[]',true);foreach($days as $day){$saved=g('SELECT choice FROM px_meals WHERE tenant_id=? AND post_id=? AND student_id=? AND meal_on=?',[$u['tenant_id'],$p['id'],$s['id'],$day]);echo '<article><time datetime="'.e($day).'">'.e(date('D, j M',strtotime($day))).'</time><p>'.e($saved?'Selected: '.$saved:'Choose for this day').'</p>';if($day>=date('Y-m-d')){echo '<form method="post"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="px_action" value="meal"><input type="hidden" name="child" value="'.(int)$s['id'].'"><input type="hidden" name="post_id" value="'.(int)$p['id'].'"><input type="hidden" name="meal_on" value="'.e($day).'"><label>Meal<select name="choice" required>';foreach($opts as $o)echo '<option '.($saved===$o?'selected':'').' value="'.e($o).'">'.e($o).'</option>';echo '</select></label><button class="btn">Save '.e(date('D',strtotime($day))).' choice</button></form>';}echo '</article>';}echo '</div></article>';}
function px_brand(int $tid):array{$t=q('SELECT * FROM tenants WHERE id=?',[$tid])->fetch();$b=['school_name'=>$t['name']??'School','motto'=>'','primary_color'=>'#08796e','phone'=>'','email'=>'','address'=>'','website'=>'','logo_url'=>''];if(xp_has('school_setup_records')){$j=g("SELECT payload FROM school_setup_records WHERE tenant_id=? AND module_key='branding' AND active=1 ORDER BY updated_at DESC,id DESC LIMIT 1",[$tid]);$d=json_decode((string)$j,true);if(is_array($d))foreach($b as $k=>$v)if(is_string($d[$k]??null))$b[$k]=$d[$k];}if(!preg_match('/^#[a-fA-F0-9]{6}$/D',$b['primary_color']))$b['primary_color']='#08796e';$logo=$b['logo_url'];if(!preg_match('~^uploads/schoolos-logos/school-'.$tid.'-[a-f0-9]{24}\.(png|jpg|webp)$~D',$logo)&&!(filter_var($logo,FILTER_VALIDATE_URL)&&parse_url($logo,PHP_URL_SCHEME)==='https'))$b['logo_url']='';return $b;}
function px_demo_seed():void{global $pdo;$teacher=(int)g("SELECT id FROM users WHERE email='teacher@demo.schoolos.test'");$admin=(int)g("SELECT id FROM users WHERE email='schooladmin@demo.schoolos.test'");$parent=(int)g("SELECT id FROM users WHERE email='parent@demo.schoolos.test'");$student=(int)g("SELECT id FROM users WHERE email='student@demo.schoolos.test'");if(!$teacher||!$admin||!$parent||!$student)throw new RuntimeException('Expected fictional demo identities are missing.');q('DELETE FROM ix_roles WHERE tenant_id=1 AND user_id=?',[$teacher]);q("INSERT INTO school_setup_records(tenant_id,module_key,record_key,payload,created_by,updated_by) VALUES(1,'branding','demo-brand',?,?,?)",[json_encode(['school_name'=>'Possibility Heights Demo School','motto'=>'Every learner. Every possibility.','address'=>'1 Fictional Learning Avenue, Demo City','phone'=>'08000000000','email'=>'office@demo.schoolos.test','website'=>'https://school.demo.invalid','primary_color'=>'#08796e']),$admin,$admin]);$session=(string)g('SELECT session_name FROM classes WHERE tenant_id=1 AND id=1');q("UPDATE ac_assessments SET weight=70 WHERE tenant_id=1 AND class_id=1 AND session_name=? AND term_name='First' AND title='Published demo assessment' AND category='exam'",[$session]);for($subject=1;$subject<=3;$subject++){q("INSERT INTO ac_assessments(tenant_id,class_id,subject_id,session_name,term_name,title,category,max_score,weight) VALUES(1,1,?,?,'First','Published continuous assessment','ca',30,30)",[$subject,$session]);$a=(int)$pdo->lastInsertId();for($sid=1;$sid<=12;$sid++)q("INSERT INTO ac_scores(tenant_id,assessment_id,student_id,score,status,entered_by,moderated_by) VALUES(1,?,?,?,'approved',?,?)",[$a,$sid,19+($sid+$subject)%11,$teacher,$admin]);}foreach([1,2] as $sid)q("INSERT IGNORE INTO op_notifications(tenant_id,student_id,kind,body,event_key) VALUES(1,?,'transport','Sunrise bus is preparing for the afternoon route. Check the manifest and verified handover arrangements.',?)",[$sid,'PX-DEMO-TRANSPORT-'.$sid]);q("UPDATE pp_posts SET starts_at=DATE_ADD(CONCAT(CURRENT_DATE(),' 14:00:00'),INTERVAL 1 DAY),ends_at=DATE_ADD(CONCAT(CURRENT_DATE(),' 16:00:00'),INTERVAL 1 DAY) WHERE tenant_id=1 AND kind='calendar'");foreach(q("SELECT id FROM pp_posts WHERE tenant_id=1 AND kind='calendar'") as $ev)q("INSERT INTO px_post_meta(tenant_id,post_id,audience,location) VALUES(1,?,'all','Fictional school discovery hall')",[$ev['id']]);q("UPDATE pp_posts SET starts_at=CONCAT(CURRENT_DATE(),' 00:00:00'),ends_at=DATE_ADD(CONCAT(CURRENT_DATE(),' 23:59:00'),INTERVAL 6 DAY) WHERE tenant_id=1 AND kind='meals'");q("INSERT INTO px_live(tenant_id,teacher_id,class_id,subject_id,session_name,title,provider,starts_at,ends_at) VALUES(1,?,1,1,?,'Patterns in everyday life · live classroom','schoolos',CONCAT(CURRENT_DATE(),' 00:00:00'),DATE_ADD(NOW(),INTERVAL 7 DAY))",[$teacher,$session]);q("INSERT INTO px_threads(tenant_id,created_by,title) VALUES(1,?,'Our learning check-in')",[$parent]);$thread=(int)$pdo->lastInsertId();foreach([$parent,$student] as $id)q('INSERT INTO px_members(tenant_id,thread_id,user_id) VALUES(1,?,?)',[$thread,$id]);q('INSERT INTO px_messages(tenant_id,thread_id,user_id,body,client_key) VALUES(1,?,?,?,?)',[$thread,$parent,'Hello Amara! What did you enjoy learning today?',bin2hex(random_bytes(16))]);q("INSERT INTO xp_config VALUES('px_demo_version','530') ON DUPLICATE KEY UPDATE value='530'");}
function px_demo_upgrade(PDO $demo):void{global $pdo;$version=$demo->query("SELECT value FROM xp_config WHERE name='px_demo_version'")->fetchColumn();if($version==='530'&&xp_setting('demo_portal_version')==='530')return;$main=$pdo;$expected=json_decode(xp_setting('demo_tables','[]'),true);$tables=$demo->query('SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() ORDER BY table_name')->fetchAll(PDO::FETCH_COLUMN);$add=['px_meals','px_threads','px_members','px_messages','px_live','px_peers','px_signals','px_post_meta'];if(!$expected||array_diff($tables,$expected,$add)||array_diff($expected,$tables,$add))throw new RuntimeException('The marked demo schema needs platform review before the portal upgrade.');$name=(string)$demo->query('SELECT DATABASE()')->fetchColumn();$lock='schoolos-demo-'.substr(hash('sha256',$name),0,32);if(!(int)$demo->query('SELECT GET_LOCK('.$demo->quote($lock).',1)')->fetchColumn())throw new RuntimeException('Demo maintenance is in progress.');try{$version=$demo->query("SELECT value FROM xp_config WHERE name='px_demo_version'")->fetchColumn();if($version!=='530'){$pdo=$demo;px_install();$demo->beginTransaction();try{px_demo_seed();$demo->commit();}catch(Throwable $e){if($demo->inTransaction())$demo->rollBack();throw $e;}}$tables=$demo->query('SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() ORDER BY table_name')->fetchAll(PDO::FETCH_COLUMN);sort($tables);$pdo=$main;q("INSERT INTO xp_config(name,value) VALUES('demo_tables',?) ON DUPLICATE KEY UPDATE value=VALUES(value)",[json_encode($tables)]);q("INSERT INTO xp_config(name,value) VALUES('demo_portal_version','530') ON DUPLICATE KEY UPDATE value='530'");}finally{$pdo=$main;$demo->query('SELECT RELEASE_LOCK('.$demo->quote($lock).')');}}
function px_number_words(int $n):string{$small=['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];$tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];if($n<20)return $small[$n];if($n<100)return $tens[intdiv($n,10)].($n%10?' '.$small[$n%10]:'');if($n<1000)return $small[intdiv($n,100)].' Hundred'.($n%100?' and '.px_number_words($n%100):'');foreach([1000000000000=>'Trillion',1000000000=>'Billion',1000000=>'Million',1000=>'Thousand'] as $scale=>$word)if($n>=$scale)return px_number_words(intdiv($n,$scale)).' '.$word.($n%$scale?' '.px_number_words($n%$scale):'');return (string)$n;}
function px_receipt(array $p):void{$b=px_brand((int)$p['tenant_id']);$amount=(int)$p['amount_kobo'];$balance=max(0,(int)$p['invoice_amount']-(int)$p['discount_kobo']+(int)$p['penalty_kobo']-(int)$p['paid_kobo']);$words=px_number_words(intdiv($amount,100)).' Naira'.($amount%100?' and '.px_number_words($amount%100).' Kobo':'').' only';header('Content-Type:text/html; charset=utf-8');header('Cache-Control: private, no-store');echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt '.e($p['reference']).' · '.e($b['school_name']).'</title><style>*{box-sizing:border-box}body{font:14px/1.7 system-ui;color:#20354a;background:#edf2f5;margin:0;padding:35px 16px}.receipt{max-width:850px;margin:auto;background:white;border-top:7px solid '.e($b['primary_color']).';box-shadow:0 15px 60px #142e4510;padding:45px;border-radius:12px}header{display:flex;gap:22px;align-items:center;border-bottom:1px solid #dbe3e8;padding-bottom:25px}header img{width:90px;height:90px;object-fit:contain}h1{font-size:26px;margin:0;line-height:1.3}header p{margin:5px 0;color:#53677a;font-size:12px}.receipt-top{display:flex;justify-content:space-between;gap:20px;align-items:start;margin:30px 0}.receipt-top h2{margin:0;font-size:23px}.verified{background:#e2f5ec;color:#165f42;padding:7px 12px;border-radius:30px;font-size:11px;font-weight:750}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}dt{font-size:11px;color:#596d7f;text-transform:uppercase;letter-spacing:1px}dd{margin:4px 0 17px;font-weight:650;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{text-align:left;padding:15px 12px;border-bottom:1px solid #dce5eb}th{background:#f3f6f8;font-size:11px;text-transform:uppercase}.amount{padding:25px;background:#f1f6f4;border-radius:12px;display:flex;justify-content:space-between;gap:20px}.amount strong{font-size:28px}.words{font-family:Georgia,serif;font-size:15px}footer{border-top:1px solid #dbe3e8;margin-top:30px;padding-top:20px;color:#596d7f;font-size:11px}.tools{max-width:850px;margin:20px auto;display:flex;justify-content:space-between;gap:20px}button{padding:12px 20px;border:0;border-radius:7px;background:#164e40;color:white;cursor:pointer}a{color:#164e40}@media(max-width:600px){.receipt{padding:24px}.grid{grid-template-columns:1fr}header img{width:60px;height:60px}h1{font-size:21px}.amount{display:block}.receipt-top{flex-wrap:wrap}}@media print{body{background:white;padding:0}.receipt{box-shadow:none;border-radius:0;padding:25px}.tools{display:none}}</style></head><body><main class="receipt"><header>';if(!$b['logo_url'])echo '<div style="width:80px;height:80px;border-radius:20px;background:#e5f2ed;display:grid;place-items:center;font-size:28px;font-weight:800;color:#164e40">'.e(mb_substr($b['school_name'],0,1)).'</div>';if($b['logo_url'])echo '<img src="'.e($b['logo_url']).'" alt="School logo">';echo '<div><h1>'.e($b['school_name']).'</h1>';if($b['motto'])echo '<p>'.e($b['motto']).'</p>';foreach(['address','phone','email','website'] as $k)if($b[$k])echo '<p>'.e($b[$k]).'</p>';echo '</div></header><div class="receipt-top"><div><h2>Official payment receipt</h2><p>Receipt reference: <b>'.e($p['reference']).'</b></p></div><span class="verified">CONFIRMED PAYMENT</span></div><div class="grid"><dl><dt>Received for</dt><dd>'.e($p['student_name']).'</dd><dt>Admission number</dt><dd>'.e($p['student_no']).'</dd><dt>Invoice reference</dt><dd>'.e($p['invoice_ref']).'</dd></dl><dl><dt>Date of confirmation</dt><dd>'.e($p['confirmed_at']).' WAT</dd><dt>Payment method</dt><dd>'.e(ucwords(str_replace('_',' ',$p['channel']))).'</dd><dt>Issued on</dt><dd>'.e(date('j F Y · H:i')).' WAT</dd></dl></div><table><thead><tr><th>Payment description</th><th>Amount received (NGN)</th></tr></thead><tbody><tr><td>'.e($p['description']).'</td><td>'.e(fnFmt($amount)).'</td></tr></tbody></table><div class="amount"><div><span>Amount acknowledged</span><p class="words">'.e($words).'</p></div><strong>'.e(fnFmt($amount)).'</strong></div><p>Invoice balance at generation: <b>'.e(fnFmt($balance)).'</b>. This figure reflects all confirmed allocations currently recorded against this invoice.</p><footer><p>Thank you. We acknowledge receipt of the payment shown above for the named learner and invoice. Please retain this receipt and quote its payment reference when contacting the school.</p><p>This receipt is generated electronically from a confirmed school payment record. It does not represent an unverified transfer or a separate tax invoice.</p></footer></main><div class="tools"><button onclick="window.print()">Print / Save PDF</button><a href="index.php?s=workspace">Return to your dashboard</a></div></body></html>';}
function px_publish_meta(array $u,int $id,string $kind):void{if($kind!=='calendar'||!px_ready())return;$aud=pp_text('event_audience',20)?:'families';if(!in_array($aud,['families','students','parents','all','staff'],true))throw new RuntimeException('Choose a valid event audience.');q('INSERT INTO px_post_meta(tenant_id,post_id,audience,location) VALUES(?,?,?,?)',[$u['tenant_id'],$id,$aud,pp_text('event_location',180)]);}
function px_post_visible(array $p,array $u):bool{if(!xp_has('px_post_meta'))return true;$aud=g('SELECT audience FROM px_post_meta WHERE tenant_id=? AND post_id=?',[$p['tenant_id'],$p['id']]);return $aud!=='staff'||in_array($u['role'],['staff','teacher','school_admin','admissions'],true);}
function px_service_area(array $u,string $area):bool{if($u['role']==='school_admin')return true;return match($area){'library'=>in_array($u['role'],['parent','student','teacher'],true)||sv_can($u,'librarian'),'inventory'=>in_array($u['role'],['parent','student','teacher'],true)||sv_can($u,'stock_manager')||sv_can($u,'procurement_approver')||sv_can($u,'asset_manager'),'engagement'=>in_array($u['role'],['parent','student','teacher'],true)||sv_can($u,'communications_manager'),'website'=>sv_can($u,'website_editor')||sv_can($u,'website_approver'),default=>false};}
function px_operation_area(array $u,string $area):bool{if($u['role']==='school_admin')return true;return match($area){'overview'=>px_can_section($u,'operations'),'hr'=>op_can($u,'hr_manager'),'transport'=>op_can($u,'transport_manager')||op_can($u,'driver'),'boarding'=>op_can($u,'boarding_manager')||op_can($u,'warden'),default=>false};}
function px_insight_area(array $u,string $area):bool{if($u['role']==='school_admin')return true;$caps=match($area){'reports'=>['reports_view','finance_reports','hr_reports'],'innovations'=>['success_reviewer','pickup_officer','flow_approver'],'academics'=>['curriculum_manager','timetable_manager'],'wallet'=>['wallet_cashier'],'governance'=>['alumni_manager','accreditation_manager','privacy_officer','group_analyst','integration_manager'],default=>[]};foreach($caps as $cap)if(ix_can($u,$cap))return true;return false;}
function px_learning_hub(array $u):void{if(isset($_GET['view'])&&!in_array($_GET['view'],['dashboard','classes','courses'],true))return;echo '<section class="px-learning-hub"><div><span class="px-kicker">'.($u['role']==='student'?'YOUR NEXT DISCOVERY':'YOUR NEXT TEACHING MOMENT').'</span><h3>'.($u['role']==='student'?'Keep your curiosity moving.':'Plan. Connect. Inspire.').'</h3><p>'.($u['role']==='student'?'Continue a learning activity, join a live lesson or plan your study time.':'Organize courses, publish activities and meet your allocated learners.').'</p><a class="btn" href="?s=learning&amp;view=live">Open live classroom →</a></div><div class="px-course-grid">';foreach(array_slice(lp_courses($u),0,8) as $c){echo '<article class="px-course"><span>COURSE</span><h3>'.e($c['title']).'</h3><p>'.e(mb_substr($c['description']??'',0,150)).'</p><small>'.e($c['status']).'</small><a href="?s=learning&amp;view='.($u['role']==='student'?'homework':'assignments').'&amp;course='.(int)$c['id'].'">'.($u['role']==='student'?'Explore activities':'Manage activities').' →</a></article>';}echo '</div></section>';}
function px_shell(array $u):void{echo '<link rel="stylesheet" href="portal_experience.css?v=530"><script src="portal_experience.js?v=530" defer></script><meta name="px-csrf" content="'.e($_SESSION['csrf']).'"><div class="px-role-bar" data-role="'.e($u['role']).'"><span>'.e(px_role_intro($u)[0]).'</span>';if((int)($u['tenant_id']??0)>0)echo '<a href="?s=chat">✉ School chat</a>';echo '</div>';if(isset($_SESSION['px_notice'])){px_notice((string)$_SESSION['px_notice']);unset($_SESSION['px_notice']);}if($u['role']!=='platform_super_admin'&&(int)($u['tenant_id']??0)>0){echo '<section class="px-alert-centre" aria-label="School updates"><div><span class="px-live-dot" aria-hidden="true"></span><b>Your important updates</b><button type="button" id="pxAlertSound" aria-pressed="false">Sound off</button><button type="button" id="pxAlertPause" aria-pressed="false">Pause rotation</button></div><div id="pxAlerts"><p class="muted">Checking your school updates…</p></div></section>';if(!px_ready())echo '<div class="px-setup-note">New conversation, live classroom and daily-meal tools need Portal Experience activation. '.($u['role']==='school_admin'?'Open Setup & Accounts and activate the installed workspaces.':'Your school administrator can complete this setup.').'</div>';}}
function px_action(array $u):string{xp_csrf();$a=xp_text('px_action',40);if($a==='activate'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');px_install();return 'Portal Experience activated. Existing school records preserved.';}if(!px_ready())throw new RuntimeException('Ask the school administrator to activate Portal Experience.');if($a==='meal')return px_meal_save($u);if($a==='chat_start'){$id=px_chat_start($u);$_SESSION['px_thread_redirect']=$id;return 'Conversation created and your message delivered.';}if($a==='live_create')return px_live_create($u);if($a==='live_end'){$r=px_live_scope($u,(int)xp_text('lesson_id',20));if((int)$r['teacher_id']!==(int)$u['id']&&$u['role']!=='school_admin')throw new RuntimeException('Lesson host required.');q("UPDATE px_live SET status='ended' WHERE tenant_id=? AND id=?",[$u['tenant_id'],$r['id']]);q('DELETE FROM px_peers WHERE tenant_id=? AND lesson_id=?',[$u['tenant_id'],$r['id']]);return 'Live lesson ended. Participants can no longer join.';}if($a==='live_settings'){if($u['role']!=='school_admin'||defined('SCHOOLOS_DEMO_MODE'))throw new RuntimeException('Only a live school administrator can configure a media relay.');$url=xp_text('turn_url',500,false);$secret=xp_text('turn_secret',500,false);if(!$url&&!$secret)return 'Existing relay settings retained.';if(!preg_match('~^turns?:[a-zA-Z0-9.-]+:[0-9]{2,5}(\?transport=(udp|tcp))?$~D',$url)||strlen($secret)<20)throw new RuntimeException('Enter a TURN URL and a shared secret of at least 20 characters.');sv_save_secret((int)$u['tenant_id'],'classroom_turn_url',$url);sv_save_secret((int)$u['tenant_id'],'classroom_turn_secret',$secret);audit('learning.relay.configured');return 'Encrypted classroom relay settings saved. Test a lesson across different networks.';}throw new RuntimeException('Unsupported portal action.');}
function px_routes():void{if(isset($_GET['px_api'])){header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');try{$u=px_actor();if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??$_SERVER['HTTP_X_CSRF_TOKEN']??'')))throw new RuntimeException('Refresh the page to renew your security token.');$a=is_string($_GET['px_api'])?$_GET['px_api']:'';$method=$_SERVER['REQUEST_METHOD']??'GET';if($method!=='POST'&&!in_array($a,['alerts','chat_fetch','live_poll'],true))throw new RuntimeException('POST required.');if(session_status()===PHP_SESSION_ACTIVE)session_write_close();if($a==='alerts')$out=['alerts'=>px_alerts($u)];else{if(!px_ready())throw new RuntimeException('Portal Experience activation required.');$id=(int)($_POST['id']??$_GET['id']??0);$out=match($a){'chat_fetch'=>['messages'=>px_chat_fetch($u,$id,(int)($_GET['after']??0))],'chat_send'=>['id'=>px_chat_send($u,$id,xp_text('body',4000),xp_text('key',32))],'live_join'=>px_live_join($u,$id),'live_poll'=>px_live_poll($u,$id,(string)($_GET['key']??''),(int)($_GET['after']??0)),default=>null};if($a==='live_signal'){px_live_signal($u,$id);$out=['saved'=>true];}if($a==='live_leave'){q('DELETE FROM px_peers WHERE tenant_id=? AND lesson_id=? AND user_id=? AND peer_key=?',[$u['tenant_id'],$id,$u['id'],xp_text('key',32)]);$out=['left'=>true];}if($out===null)throw new RuntimeException('Unknown portal endpoint.');}echo json_encode(['ok'=>true]+$out,JSON_THROW_ON_ERROR);}catch(Throwable $e){http_response_code(403);echo json_encode(['ok'=>false,'error'=>$e instanceof PDOException?'This school service is unavailable. Ask your administrator to check activation.':$e->getMessage()]);}exit;}
if(isset($_POST['px_action'])){try{$u=px_actor();$_SESSION['px_notice']=px_action($u);}catch(Throwable $e){$_SESSION['px_notice']='Error: '.($e instanceof PDOException?'Unable to complete this request. Contact your school administrator.':$e->getMessage());}$redirect='index.php?s=workspace';$a=$_POST['px_action']??'';if($a==='meal')$redirect='index.php?s=family&view=meals&child='.(int)($_POST['child']??0);elseif(str_starts_with((string)$a,'live_'))$redirect='index.php?s=learning&view=live';elseif($a==='chat_start'){$redirect='index.php?s=chat';if(isset($_SESSION['px_thread_redirect'])){$redirect.='&thread='.(int)$_SESSION['px_thread_redirect'];unset($_SESSION['px_thread_redirect']);}}header('Location:'.$redirect,true,303);exit;}
if(me()&&($_GET['s']??'')==='services'&&isset($_GET['area'])&&!px_service_area(me(),(string)$_GET['area'])){http_response_code(403);exit('This service is not assigned to your role.');}if(me()&&($_GET['s']??'')==='intelligence'&&isset($_GET['area'])&&!px_insight_area(me(),(string)$_GET['area'])){http_response_code(403);exit('This insight area is not assigned to your role.');}if(me()&&($_GET['s']??'')==='operations'&&!px_can_section(me(),'operations')){$area=$_GET['area']??'';$role=me()['role'];if(in_array($role,['parent','student'],true)&&in_array($area,['transport','boarding'],true)){if($role==='parent'){$_GET['s']='family';$_GET['view']=$area;}else{$_GET['s']='school_day';$_GET['view']=$area;}}elseif(in_array($role,['teacher','staff'],true)&&($area==='hr'||isset($_GET['op_payslip'])||isset($_GET['op_hr_file']))){$_GET['s']='employment';$_GET['area']='hr';}}if(me()&&in_array($_GET['s']??'',['operations','intelligence'],true)&&!px_can_section(me(),(string)$_GET['s'])){http_response_code(403);exit('This workspace is not assigned to your role. Use your own portal overview.');}}
function px_feature_navigation(array $tabs,string $view,string $module,string $suffix=''):void{$sets=$module==='family'?['Your family'=>['children'],'Learning & progress'=>['results','attendance','homework'],'Money & receipts'=>['fees','receipts'],'Plan the week'=>['calendar','bookings','meals'],'Talk & participate'=>['messages','support','surveys'],'Safety & care'=>['absence','pickup','transport','boarding'],'Permissions & files'=>['consent','documents']]:($module==='teacher'?['Plan & teach'=>['classes','timetable','lessons','syllabus','resources','live'],'Assess & support'=>['assignments','questions','scores','bulk','corrections','analytics'],'Your professional day'=>['messages','incidents','leave','pd','ai','manage']]:['Learn & practise'=>['dashboard','timetable','homework','resources','live','cbt'],'Your progress'=>['grades','attendance','feedback','badges','planner'],'School life'=>['announcements','clubs','library','ai']]);echo '<div class="px-feature-navigator" aria-label="'.e($module).' feature groups">';foreach($sets as $title=>$keys){$active=in_array($view,$keys,true);echo '<details class="px-feature-group"'.($active?' open':'').'><summary>'.e($title).($active?' <span>Current</span>':'').'</summary><nav class="'.($module==='family'?'pp-nav':'lp-tabs').'" aria-label="'.e($title).'">';foreach($keys as $key)if(isset($tabs[$key]))echo '<a '.($view===$key?'aria-current="page"':'').' href="?s='.($module==='family'?'family':'learning').$suffix.'&amp;view='.e($key).'">'.e($tabs[$key]).'</a>';echo '</nav></details>';}echo '</div>';}
function px_transport_view(array $u,array $s):void{echo '<section class="px-transport"><h3>Your child’s transport</h3>';if(xp_has('tm_assignments'))foreach(q('SELECT r.name route,v.name vehicle,st.name stop FROM tm_assignments a JOIN tm_routes r ON r.id=a.route_id AND r.tenant_id=a.tenant_id LEFT JOIN vehicles v ON v.id=r.vehicle_id AND v.tenant_id=r.tenant_id LEFT JOIN tm_stops st ON st.id=a.stop_id AND st.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.student_id=?',[$u['tenant_id'],$s['id']]) as $r)echo '<div class="px-profile"><div><span class="px-kicker">ASSIGNED ROUTE</span><h3>'.e($r['route']).'</h3><p>'.e($r['vehicle'].' · '.$r['stop']).'</p></div></div>';if(xp_has('op_notifications'))pp_table(q('SELECT kind,body,created_at FROM op_notifications WHERE tenant_id=? AND student_id=? ORDER BY id DESC LIMIT 30',[$u['tenant_id'],$s['id']])->fetchAll(),['Update','Details','Time · WAT']);echo '</section>';}
function px_student_path(array $u,array $s):void{echo '<div class="px-study-path"><h3>Your course map</h3><p>Choose an activity, continue your learning and see what you have completed.</p>';foreach(lp_courses($u) as $c){$lessons=q('SELECT l.*,p.completed_at FROM lm_lessons l LEFT JOIN lm_progress p ON p.lesson_id=l.id AND p.tenant_id=l.tenant_id AND p.student_id=? WHERE l.tenant_id=? AND l.course_id=? AND (l.available_at IS NULL OR l.available_at<=NOW()) ORDER BY l.position,l.id LIMIT 100',[$s['id'],$u['tenant_id'],$c['id']])->fetchAll();$complete=count(array_filter($lessons,fn($l)=>$l['completed_at']!==null));echo '<article class="px-course"><h3>'.e($c['title']).'</h3><label>'.(int)$complete.' / '.count($lessons).' available activities completed<progress max="'.max(1,count($lessons)).'" value="'.$complete.'"></progress></label><ol>';foreach($lessons as $l)echo '<li><a href="?s=learning&amp;view='. (in_array($l['lesson_type'],['homework','quiz'],true)?'homework':'resources').'&amp;course='.(int)$c['id'].'#activity-'.(int)$l['id'].'">'.e($l['title']).'</a><span>'.($l['completed_at']?'✓ Completed':e($l['lesson_type'])).'</span></li>';echo '</ol></article>';}echo '</div>';}
function px_default_service(array $u):string{foreach(['library','inventory','engagement','website'] as $area)if(px_service_area($u,$area))return $area;return 'library';}

function px_demo_relay(array $u):string{global $pdo;if($u['role']!=='platform_super_admin'||defined('SCHOOLOS_DEMO_MODE')||xp_text('demo_relay_confirm',10,false)!=='yes')throw new RuntimeException('Live platform administrator confirmation required.');$url=xp_text('turn_url',500);$secret=xp_text('turn_secret',500);if(!preg_match('~^turns?:[a-zA-Z0-9.-]+:[0-9]{2,5}(\?transport=(udp|tcp))?$~D',$url)||strlen($secret)<20)throw new RuntimeException('Use a dedicated demo TURN endpoint and a shared secret of at least 20 characters.');$main=$pdo;$demo=xp_demo_connection();try{$pdo=$demo;sv_save_secret(1,'classroom_turn_url',$url);sv_save_secret(1,'classroom_turn_secret',$secret);}finally{$pdo=$main;}audit('experience.demo.relay.configured');return 'Dedicated demo relay configured. Live school provider credentials were not copied.';}
function px_demo_relay_snapshot(PDO $demo):array{global $pdo;$main=$pdo;try{$pdo=$demo;return array_intersect_key(sv_secrets(1),array_flip(['classroom_turn_url','classroom_turn_secret']));}finally{$pdo=$main;}}
function px_service_title(array $u):string{if($u['role']==='school_admin')return 'School Services';if(in_array($u['role'],['parent','student'],true))return 'Your library & school store';return match(px_default_service($u)){'library'=>'Library desk','inventory'=>'Stock, procurement & assets','engagement'=>'Communication studio','website'=>'School website studio',default=>'Your service desk'};}
function px_operation_title(array $u):string{if($u['role']==='school_admin')return 'School Operations';if(op_can($u,'driver'))return 'Driver workspace';if(op_can($u,'warden'))return 'Boarding & welfare';if(op_can($u,'hr_manager'))return 'People & payroll';if(op_can($u,'transport_manager'))return 'Transport coordination';if(op_can($u,'boarding_manager'))return 'Boarding management';return 'Your assigned operations';}
function px_pickup_tokens(array $u,array $s):void{if(!xp_has('ix_pickup_tokens'))return;echo '<details class="px-composer"><summary>Time-limited pickup credential</summary><p>After the school approves today’s authorization, issue a short-lived QR/token for the verified handover. A physical identity check is still required.</p>';$approved=q("SELECT id,subject FROM pp_requests WHERE tenant_id=? AND student_id=? AND user_id=? AND kind='pickup' AND status='approved' AND starts_on=CURRENT_DATE() ORDER BY id DESC",[$u['tenant_id'],$s['id'],$u['id']])->fetchAll();if($approved){echo '<form method="post" class="px-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="ix_action" value="si_pickup_issue"><input type="hidden" name="px_return_family" value="'.(int)$s['id'].'"><label>Approved collector<select name="authorization_id">';foreach($approved as $a)echo '<option value="'.(int)$a['id'].'">'.e($a['subject']).'</option>';echo '</select></label><label>Credential lifetime in minutes<input name="minutes" type="number" min="5" max="30" value="15" required></label><button class="btn">Issue / rotate pickup credential</button></form>';}else echo '<p>No approved authorization for this child today.</p>';if(isset($_SESSION['ix_pickup_once'])){$token=$_SESSION['ix_pickup_once'];echo lib_qr($token).'<p>Copy once: <code>'.e($token).'</code></p>';unset($_SESSION['ix_pickup_once']);}pp_table(q('SELECT t.id,r.subject,t.expires_at,t.status FROM ix_pickup_tokens t JOIN pp_requests r ON r.id=t.authorization_id AND r.tenant_id=t.tenant_id WHERE t.tenant_id=? AND t.student_id=? AND t.issued_by=? ORDER BY t.id DESC LIMIT 20',[$u['tenant_id'],$s['id'],$u['id']])->fetchAll(),['Credential','Collector','Expires · WAT','Status']);echo '</details>';}
function px_student_day(array $u):void{$s=lp_student($u);echo '<section class="lp-hero"><h2>Your school day</h2><p>Transport and boarding information for '.e($s['name']).' · '.e($s['class_name']).'.</p></section><nav class="lp-tabs"><a href="?s=school_day&amp;view=transport">My transport</a><a href="?s=school_day&amp;view=boarding">My boarding</a></nav>';if(($_GET['view']??'transport')==='boarding')bd_render($u);else px_transport_view($u,$s);}
function px_default_insight(array $u):string{foreach(['reports','innovations','academics','wallet','governance'] as $area)if(px_insight_area($u,$area))return $area;return 'reports';}
